import {UNITS,MERCENARIES,WAVES,BUILDERS,ARCHIVE_UNITS,REFERENCE,RULES,ITEMS,TECHNOLOGIES,SPECIAL_MONSTERS,UNIT_TEMPLATES} from './data.js';
import {describeSkills} from './skills.js';
import {unitIcon} from './renderer.js';
import {isAppearanceVariant,appearanceBaseLabel,splitUnitCategories,documentUnit,unitDisplayName,unitCategory,unitCategoryLabel,unitSearchText} from './unit-categories.js';
import {DOCUMENT_CATALOG,DOCUMENT_CATALOG_META} from './document-catalog.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attack={normal:'普通',pierce:'穿刺',magic:'魔法',chaos:'混乱',siege:'攻城',hero:'英雄'};
const armor={heavy:'重甲',medium:'中甲',light:'轻甲',fortified:'城甲',unarmored:'无甲',hero:'英雄甲',divine:'神圣甲'};
const sourceKinds=new Set(['item','technology','special']);
const sourceKindLabels={item:'物品来源记录',technology:'科技来源记录',special:'特殊怪物'};
export const SOURCE_CATALOG_RECORDS=[...Object.values(ITEMS).map(u=>({...u,id:'item_'+u.rawcode,sourceRawcode:u.rawcode,kind:'item'})),...Object.values(TECHNOLOGIES).map(u=>({...u,id:'technology_'+u.rawcode,sourceRawcode:u.rawcode,kind:'technology'})),...[
 {...SPECIAL_MONSTERS.waveFive,spawnRule:SPECIAL_MONSTERS.waveFive,waveNumber:5},
 ...SPECIAL_MONSTERS.treasure.byWave.map(entry=>({...entry,spawnRule:SPECIAL_MONSTERS.treasure,waveNumber:entry.wave}))
].map(rule=>({...UNIT_TEMPLATES[rule.rawcode],...rule,id:'special_'+rule.rawcode,sourceRawcode:rule.rawcode,kind:'special',fields:UNIT_TEMPLATES[rule.rawcode]?.sourceRawFields??{},objectSource:UNIT_TEMPLATES[rule.rawcode]?.source,availability:'scripted-spawn'}))];
const all=[...UNITS.filter(u=>!u.legacy).map(u=>({...u,kind:'defense'})),...ARCHIVE_UNITS.map(u=>({...u,kind:'defense',unconfirmed:true})),...MERCENARIES.map(u=>({...u,kind:'attack'})),...WAVES.map(u=>({...u,id:'wave_'+u.id,kind:'wave',waveNumber:u.id})),...SOURCE_CATALOG_RECORDS];
let dialog,kind='defense',builder='all',category='all',query='',selected=null;
const categoryOptions=['基础兵种','普通升级兵种','彩蛋兵种','彩蛋兵种（待核定）','彩蛋后续升级','外观款','权益变体','变形入口','入口待确认','英雄','英雄入口','神秘礼物训练'];
const categoryKey=u=>({'基础兵种':'base','普通升级兵种':'normal','彩蛋兵种':'easter','彩蛋兵种（待核定）':'pending','彩蛋后续升级':'followup','外观款':'appearance','权益变体':'entitlement'}[unitCategory(u)]||'other');
const labelForCode=code=>unitDisplayName(UNITS.find(u=>!u.legacy&&u.sourceRawcode===code))||DOCUMENT_CATALOG[code]?.name||code;
const n=v=>Number.isFinite(v)?Number(v.toFixed(2)).toLocaleString('zh-CN'):'待核定';
export function sourceCatalogSearchText(record){return [record.name,record.rawcode,record.sourceRawcode,record.description,sourceKindLabels[record.kind],record.kind==='special'?`第${record.waveNumber}波 波次事件 奖励`:'',...Object.entries(record.fields??{}).flat()].join(' ').toLowerCase();}
const evidenceLabel=s=>s?.table?`CSV ${s.table} · 第${s.row}行`:s?.file?`${s.file}${s.function?` · ${s.function}`:''} · 第${s.line}${s.endLine&&s.endLine!==s.line?`—${s.endLine}`:''}行`:'';
export function sourceCatalogDetailMarkup(u){
 const special=u.kind==='special',rule=u.spawnRule??{},isFive=special&&u.waveNumber===5;
 const sources=[u.source,u.objectSource,rule.source,rule.initializationSource,rule.selectionSource,rule.batchSource,rule.creationHpScale?.source,isFive?rule.firstAndLastKillReward?.source:null].filter(Boolean);
 const evidence=[...new Set(sources.map(evidenceLabel).filter(Boolean))];
 const notice=special?(isFive?`第5波最后一批普通怪出现时，每条活跃路额外出现1只。最大生命${rule.maxHp}，第${rule.setCurrentHpLane}路显式设置当前生命${rule.laneOneCurrentHp}，持续${rule.lifetimeSeconds}秒。全局首只和最后一只击杀分别奖励${rule.firstAndLastKillReward.gold}金、${rule.firstAndLastKillReward.wood}木；不领取普通怪赏金。`:`第${u.waveNumber}波普通怪刷完后的下一批出现；每队随机选择一名存活玩家，在其路线生成1只。九倍出生钩子对符合条件的宝藏怪生命：第6—10波×${rule.creationHpScale.throughWave10}，第11波起×${rule.creationHpScale.fromWave11}。`):`这是解析包中的完整${u.kind==='item'?'物品':'科技'}对象记录。对象表不单独证明其${u.kind==='item'?'商店购买':'研究'}入口，此处仅供查阅；已确认入口按对应游戏菜单开放。未填写的价格、效果和条件保留缺省。`;
 const stats=special?`<div class="catalog-stats">${[['对象生命',u.hp],['出生生命',u.hp*(u.waveNumber<=10?rule.creationHpScale?.throughWave10??1:rule.creationHpScale?.fromWave11??1)],['攻击均值',u.damage],['护甲',u.armor]].map(([k,v])=>`<span>${k}<b>${n(v)}</b></span>`).join('')}</div>`:'';
 const treasure=special&&!isFive?'<p>宝藏怪死亡后留下奖励选项：金币、木材、国王护甲或己方单位护甲。第10波和第14波提升奖励等级，第14波起增加伐木升级选项。</p>':'';
 return `<div class="catalog-unit-heading"><span class="catalog-source-symbol" aria-hidden="true">${u.kind==='item'?'◇':u.kind==='technology'?'⌘':'✦'}</span><span><small>${esc(sourceKindLabels[u.kind])}${special?` · 第${u.waveNumber}波`:' · 仅来源记录'}</small><h3>${esc(u.name)}</h3><p>${esc(u.sourceRawcode)}</p></span></div><p class="catalog-notice">${esc(notice)}</p>${stats}${treasure}${u.description?`<p>${esc(u.description)}</p>`:''}${special?`<h4>对象技能</h4>${skillMarkup(u)}`:''}<h4>来源证据</h4><ul class="catalog-evidence">${evidence.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><h4>原始字段</h4><p class="catalog-source">字段名及数值按来源保留。空白与“_”不生成默认值；rawcode 大小写是对象标识的一部分。</p><dl class="catalog-raw-fields">${Object.entries(u.fields??{}).map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`;
}
export function skillMarkup(def){
 const skills=describeSkills(def);
 if(!skills.length)return '<p class="catalog-empty">没有静态技能挂载。武器与脚本机制另计。</p>';
 return skills.map(a=>`<article class="skill-entry ${a.status==='unresolved'?'unresolved':''}"><div><b>${esc(a.name||a.id||a.rawcode)}</b><span>${a.status==='implemented'?'参与模拟':a.status==='marker'?'状态标记':a.status==='partial'?'部分实现':'待核定'}</span></div><p>${esc(a.effectText||a.description||'缺少可解释的基础配置。')}</p><small>${esc(a.id||a.rawcode||'')}${a.cooldown?` · 冷却 ${n(a.cooldown)}秒`:''}${a.manaCost?` · 消耗 ${n(a.manaCost)}魔法`:''}</small></article>`).join('');
}
function init(){
 if(dialog)return;dialog=document.createElement('dialog');dialog.id='catalog-dialog';dialog.className='catalog-dialog';
 dialog.innerHTML=`<header class="dialog-header"><span><small>v14.1A5 · X9 COMPENDIUM</small><h2>兵种与资料图鉴</h2></span><button class="catalog-close" aria-label="关闭图鉴">×</button></header><div class="catalog-filters"><div class="catalog-kinds" role="tablist"><button data-kind="defense" role="tab">防守兵种</button><button data-kind="attack" role="tab">进攻木怪</button><button data-kind="wave" role="tab">35波怪物</button><button data-kind="special" role="tab">特殊怪物</button><button data-kind="item" role="tab">物品来源</button><button data-kind="technology" role="tab">科技来源</button></div><div class="catalog-search"><select class="catalog-builder-filter" aria-label="按建造者筛选"><option value="all">全部建造者</option>${BUILDERS.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select><select class="catalog-category-filter" aria-label="按兵种分类筛选"><option value="all">全部兵种分类</option><option value="recipe">彩蛋配方 · 32确认＋2待核定</option>${categoryOptions.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><input type="search" placeholder="搜索名称、rawcode、技能或原始字段" aria-label="搜索图鉴内容"></div></div><div class="catalog-body"><div class="catalog-list" aria-label="图鉴记录列表"></div><section class="catalog-detail" aria-live="polite"></section></div><footer class="catalog-footer">文档确认${DOCUMENT_CATALOG_META.confirmedRecipes}项彩蛋配方，另${DOCUMENT_CATALOG_META.pendingRecipes}项待核定。紫色为外观／权益，皮肤不作为配方；完成历史、首次在场与升级载体分别注明。</footer>`;
 document.body.append(dialog);dialog.querySelector('.catalog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 dialog.querySelector('.catalog-kinds').onclick=e=>{const b=e.target.closest('[data-kind]');if(!b)return;kind=b.dataset.kind;selected=null;renderList();};
 dialog.querySelector('input').oninput=e=>{query=e.target.value.trim().toLowerCase();renderList();};
 dialog.querySelector('.catalog-builder-filter').onchange=e=>{builder=e.target.value;renderList();};
 dialog.querySelector('.catalog-category-filter').onchange=e=>{category=e.target.value;renderList();};
 dialog.querySelector('.catalog-list').onclick=e=>{const b=e.target.closest('[data-record]');if(b){selected=b.dataset.record;renderList(false);}};
}
function renderList(resetScroll=true){
 const race=BUILDERS.find(b=>b.id===builder);
 const rows=all.filter(u=>u.kind===kind).filter(u=>!race||kind!=='defense'||u.hero||u.builderIds?.includes(builder)||u.race===race.name||race.rosterIds?.includes(u.id)||race.heroEntryIds?.includes(u.id)).filter(u=>kind!=='defense'||category==='all'||(category==='recipe'?['confirmed','pending'].includes(documentUnit(u)?.recipeStatus):unitCategory(u)===category)).filter(u=>!query||(sourceKinds.has(u.kind)?sourceCatalogSearchText(u):`${unitSearchText(u)} ${appearanceBaseLabel(u,UNITS)} ${u.waveNumber??''} ${u.sourceRawcode} ${u.combatRawcode} ${(u.sourceAbilities||[]).map(a=>a.name).join(' ')} ${describeSkills(u).map(a=>a.name).join(' ')}`.toLowerCase()).includes(query));
 if(!rows.some(u=>u.id===selected))selected=rows[0]?.id??null;
 dialog.querySelectorAll('[data-kind]').forEach(b=>{const active=b.dataset.kind===kind;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});dialog.querySelector('.catalog-builder-filter').hidden=kind!=='defense';dialog.querySelector('.catalog-category-filter').hidden=kind!=='defense';
 const list=dialog.querySelector('.catalog-list'),oldScroll=list.scrollTop;
 list.innerHTML=rows.length?rows.map(u=>sourceKinds.has(u.kind)?`<button class="catalog-row ${u.id===selected?'active':''}" data-record="${esc(u.id)}" data-source-kind="${esc(u.kind)}"><span class="catalog-source-symbol" aria-hidden="true">${u.kind==='item'?'◇':u.kind==='technology'?'⌘':'✦'}</span><span><b>${esc(u.name)}</b><small>${esc(u.sourceRawcode)} · ${u.kind==='special'?`第${u.waveNumber}波`:'仅来源记录'}</small></span><em>${u.kind==='special'?'波次事件':u.kind==='item'?'物品':'科技'}</em></button>`:`<button class="catalog-row ${u.id===selected?'active':''}" data-record="${esc(u.id)}" data-document-category="${categoryKey(u)}">${unitIcon(u)}<span><b>${esc(u.waveNumber?`${u.waveNumber}. ${unitDisplayName(u)}`:unitDisplayName(u))}</b><small>${esc(u.kind==='defense'?`${unitCategoryLabel(u)}${isAppearanceVariant(u)?` · 本体：${appearanceBaseLabel(u,UNITS)}`:u.heroLevel?` · ${u.heroLevel}级`:''}`:u.sourceRawcode||u.id)}</small></span><em>${u.kind==='attack'?u.shopPreview?'提示变体':`${n(u.wood)}木`:u.kind==='wave'?`${n(u.count??u.referenceCount)}只`:u.cost==null?'—':`${n(u.cost)}金`}</em></button>`).join(''):'<p class="catalog-empty">没有匹配的图鉴记录</p>';
 dialog.querySelector('.catalog-footer').textContent=sourceKinds.has(kind)?`${rows.length}项${sourceKindLabels[kind]}。${kind==='special'?'波次事件、出生生命与奖励保留 JASS 证据；原始字段是对象基础值。':'仅来源记录不代表已开放购买或研究。搜索支持 rawcode 与原始字段值。'}`:`文档确认${DOCUMENT_CATALOG_META.confirmedRecipes}项彩蛋配方，另${DOCUMENT_CATALOG_META.pendingRecipes}项待核定。紫色为外观／权益，皮肤不作为配方；完成历史、首次在场与升级载体分别注明。`;
 if(!resetScroll)list.scrollTop=oldScroll;renderDetail(rows.find(u=>u.id===selected));
}
function renderDetail(u){
 const detail=dialog.querySelector('.catalog-detail');if(!u){detail.innerHTML='';return;}if(sourceKinds.has(u.kind)){detail.innerHTML=sourceCatalogDetailMarkup(u);return;}
 const record=documentUnit(u),appearance=isAppearanceVariant(u),targets=(u.upgrades||[]).map(id=>UNITS.find(p=>p.id===id)).filter(Boolean);
 const parents=UNITS.filter(p=>!p.legacy&&p.upgrades?.includes(u.id)),groups=splitUnitCategories(targets);
 const trainingParents=UNITS.filter(p=>!p.legacy&&p.trainTargets?.includes(u.id)),trainingTargets=(u.trainTargets??[]).map(id=>UNITS.find(p=>!p.legacy&&p.id===id)).filter(Boolean);
 const training=trainingParents.length||trainingTargets.length?`<div class="catalog-upgrades"><p><b>神秘礼物·兵种训练：</b>第6波清完后抽取的三项礼物可能包含训练。成功时消耗整组礼物，立即替换并支付目标物编价格的40%，仍需满足目标资格、科技与数量条件。第13波清完时旧礼物会被替换。</p>${trainingParents.length?`<p>训练来源：${trainingParents.map(p=>esc(unitDisplayName(p))).join('、')}。</p>`:''}${trainingTargets.length?`<p>训练目标：${trainingTargets.map(t=>`${esc(unitDisplayName(t))}（${Math.trunc(t.cost*.4)}金${t.woodCost?`＋${Math.trunc(t.woodCost*.4)}木`:''}）`).join('、')}。</p>`:''}</div>`:'';
 const source=u.source||u.workbookSource||u.sourceWorkbook||u.workbook||{};
 const heading=`<div class="catalog-unit-heading">${unitIcon(u,64)}<span><small>${esc(u.race||(u.kind==='wave'?'系统怪':'佣兵'))}${u.kind==='defense'?` · ${esc(unitCategoryLabel(u))}`:''}</small><h3>${esc(unitDisplayName(u))}</h3><p>${esc(u.sourceRawcode||'')} ${u.combatRawcode?` → ${esc(u.combatRawcode)}`:''}</p></span></div>`;
 const documentFacts=record?`<div class="catalog-document-facts" data-document-category="${categoryKey(u)}"><p><b>兵种分类：</b>${esc(record.category)}</p><p><b>获得方式：</b>${esc(record.acquisitionText)}</p>${appearance?`<p><b>对应本体：</b>${esc(appearanceBaseLabel(u,UNITS))}（${esc(record.baseCategory)}，${esc(record.baseRawcode)}）。${record.branchKind==='appearance'?'外观与本体属于同一兵种体系。':'这是账号／商城权益分支，未据此认定为纯外观等价。'}</p><p><b>实际入口：</b>${record.actualParentRawcodes.map(code=>esc(labelForCode(code))).join('、')||'待核定'}。本体与升级入口分别列出。</p>`:''}<p><b>${appearance?'分支使用条件':'解锁条件'}：</b>${esc(record.conditionText.replace(/^分支使用条件：/,''))}</p>${record.recipe?`<p class="catalog-notice ${record.recipeStatus==='pending'?'catalog-pending':''}"><b>${record.recipeStatus==='pending'?'配方路径待核定':'已确认彩蛋配方'}</b> · 由${esc(record.recipe.sourceLabel)}升级为${esc(unitDisplayName(u))}。${esc(record.recipe.conditionText)}；${esc(record.recipe.limitText)}。</p>`:record.recipeStatus==='followup'?'<p class="catalog-notice">彩蛋的后续升级，需要原有账号资格；不计入32项彩蛋合成配方。</p>':appearance?'<p class="catalog-notice">外观／权益分支单列，不作为彩蛋合成配方或消耗材料。</p>':''}</div>`:'';
 const upgradeMarkup=(units,label)=>units.length?`<p>${label}：${units.map(t=>`${esc(unitDisplayName(t))}（${n(t.cost)}金${t.woodCost?`＋${n(t.woodCost)}木`:''}）`).join('、')}</p>`:'';
 const upgrades=parents.length||targets.length?`<div class="catalog-upgrades">${parents.length?`<p>实际升级来源：${parents.map(p=>`${esc(unitDisplayName(p))}（${esc(unitCategoryLabel(p))}）`).join('、')}</p>`:''}${upgradeMarkup(groups.normal,u.heroEntry?'英雄选择':u.hero?'英雄升级':'普通升级')}${upgradeMarkup(groups.easter,'彩蛋升级')}${upgradeMarkup(groups.pending,'彩蛋路径待核定')}${upgradeMarkup(groups.followups,'彩蛋后续升级')}${upgradeMarkup(groups.appearances.filter(t=>unitCategory(t)==='外观款'),'外观选项')}${upgradeMarkup(groups.entitlements,'权益分支')}</div>`:'';
 detail.innerHTML=heading+documentFacts+`${u.unconfirmed?'<p class="catalog-notice">该记录尚未开放直接建造，请核对来源、条件或资格限制。</p>':''}${u.morphProxy?'<p class="catalog-notice">该建筑完成后从对应阶数候选池随机变形，不作为最终战斗单位。</p>':''}<div class="catalog-stats">${[['生命',u.hp],['攻击均值',u.damage],['护甲',u.armor],['间隔秒',u.interval],['原始射程',u.sourceRange],['人口',u.population],['魔法上限',u.maxMana??u.manaMax??u.mana],['魔法回复',u.manaRegen]].map(([k,v])=>`<span>${k}<b>${n(v)}</b></span>`).join('')}</div><p class="catalog-type">${attack[u.attackType]||esc(u.attackType||'待核定')}攻击 / ${esc(u.armorDisplayName)||armor[u.armorType]||esc(u.armorType||'待核定')}${u.woodCost?` · ${n(u.woodCost)}木`:''}</p>${u.shopPreview?'<p class="catalog-notice">这是来源中的提示／受限变体，静态数据没有可售库存，不作为普通商品开放。</p>':''}${u.kind==='attack'?`<p>库存 ${n(u.stockMax)}，补货 ${n(u.cooldown)}秒，第${n(u.unlock)}波起开放${u.availableUntilWave?`，第${n(u.availableUntilWave)}波后切换`:''}。收入：1—10波 +${n(u.income)}，11波起 +${n(u.incomeLate??Math.floor(u.income/2))}。</p>`:''}${upgrades}${training}${u.omittedUpgradeRawcodes?.length?`<p class="catalog-notice">未解析升级目标：${u.omittedUpgradeRawcodes.map(esc).join('、')}。保留原始大小写，暂不开启此分支。</p>`:''}${!record&&(u.requiresDetails?.length||u.requirements?.length)?`<p class="catalog-notice">获取条件：${(u.requiresDetails??u.requirements).map(r=>esc(typeof r==='string'?r:r.name||r.rawcode)).join('、')}</p>`:''}<h4>技能与机制</h4>${skillMarkup(u)}<p class="catalog-source">${record?`分类与条件：修订文档“${esc(record.source.table)}”第${record.source.record}条；原始代码及技能、价格按来源保留。`:''}${source.table?`CSV：${esc(source.table)}，第${esc(source.row)}行。`:source.sheet?`历史Excel：${esc(source.sheet)}，第${esc(source.row)}行。`:'v14原始物编、单位技能关联与脚本证据。'}${esc(u.availability||u.reachability||'')}</p>`;
}
export function openCatalog(id=null){init();if(id){const u=all.find(u=>u.id===id||u.sourceRawcode===id);if(u){kind=u.kind;selected=u.id;builder='all';category='all';query='';dialog.querySelector('input').value='';dialog.querySelector('.catalog-builder-filter').value='all';dialog.querySelector('.catalog-category-filter').value='all';}}renderList();if(!dialog.open)dialog.showModal();}
